B.b_v=new A.d('\u042d\u0442\u0430 \u043e\u0446\u0435\u043d\u043a\u0430 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u0438\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u043d\u0446\u0438\u043f \u043f\u043b\u0430\u043d\u0435\u0442\u044b "\u0432\u0441\u0442\u0440\u043e\u0435\u043d" \u0432 \u044f\u0434\u0440\u043e \u0432\u0430\u0448\u0435\u0439 \u043b\u0438\u0447\u043d\u043e\u0441\u0442\u0438.',null,B.b,null,null)
