B.aTk=new A.d('\u041c\u0430\u0440\u0441 \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u043e\u0435 \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435: \u044d\u0442\u043e \u043f\u0435\u0440\u0432\u0430\u044f \u043f\u043b\u0430\u043d\u0435\u0442\u0430 \u0441 \u043e\u0440\u0431\u0438\u0442\u043e\u0439 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u043f\u043e \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044e \u043a \u0417\u0435\u043c\u043b\u0435. \u0415\u0433\u043e \u0446\u0438\u043a\u043b \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0434\u043b\u0438\u043d\u043d\u0435\u0435 \u0433\u043e\u0434\u043e\u0432\u043e\u0433\u043e \u0446\u0438\u043a\u043b\u0430 \u0417\u0435\u043c\u043b\u0438/\u0421\u043e\u043b\u043d\u0446\u0430 (\u0441\u0432\u044f\u0437\u0430\u043d\u043d\u043e\u0433\u043e \u0441 \u0431\u0430\u0437\u043e\u0432\u044b\u043c \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u0435\u043c \u0438 \u0441\u043e\u0437\u043d\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0446\u0435\u043b\u0435\u043f\u043e\u043b\u0430\u0433\u0430\u043d\u0438\u0435\u043c) \u0438 \u0446\u0438\u043a\u043b\u043e\u0432 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0445 \u043f\u043b\u0430\u043d\u0435\u0442 (\u041c\u0435\u0440\u043a\u0443\u0440\u0438\u044f \u0438 \u0412\u0435\u043d\u0435\u0440\u044b, \u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0449\u0438\u0445 \u0437\u0430 \u043a\u0440\u0430\u0442\u043a\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u044b \u0438 \u043b\u0438\u0447\u043d\u044b\u0435 \u0436\u0435\u043b\u0430\u043d\u0438\u044f). \u042d\u0442\u043e \u043f\u043e\u0437\u0438\u0446\u0438\u043e\u043d\u0438\u0440\u0443\u0435\u0442 \u041c\u0430\u0440\u0441 \u043a\u0430\u043a \u043f\u0440\u0438\u043d\u0446\u0438\u043f, \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0439 \u0441 \u0430\u043a\u0442\u0438\u0432\u043d\u044b\u043c \u043f\u0440\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u0432\u043e\u043b\u0438 \u0432\u043e \u0432\u043d\u0435\u0448\u043d\u0435\u043c \u043c\u0438\u0440\u0435, \u0442\u0440\u0435\u0431\u0443\u044e\u0449\u0438\u043c \u0441\u0440\u0435\u0434\u043d\u0435\u0441\u0440\u043e\u0447\u043d\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0443\u0441\u0438\u043b\u0438\u0439.\n\n\u0415\u0441\u043b\u0438 \u0417\u0435\u043c\u043b\u044f/\u0421\u043e\u043b\u043d\u0446\u0435 \u2013 \u044d\u0442\u043e \u0441\u043e\u0437\u043d\u0430\u043d\u0438\u0435 \u0438 \u0432\u043e\u043b\u044f \u043a \u0436\u0438\u0437\u043d\u0438, \u0430 \u0412\u0435\u043d\u0435\u0440\u0430 \u2013 \u043b\u0438\u0447\u043d\u044b\u0435 \u0436\u0435\u043b\u0430\u043d\u0438\u044f \u0438 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u0442\u043e \u041c\u0430\u0440\u0441 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u043e\u0431\u043e\u0439 "\u043f\u0440\u0438\u043d\u0446\u0438\u043f \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f", \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0430 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u0435 \u044d\u0442\u0438\u0445 \u0436\u0435\u043b\u0430\u043d\u0438\u0439 \u0438 \u0437\u0430\u0449\u0438\u0442\u0443 \u0441\u0432\u043e\u0438\u0445 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u043e\u0432 \u0432\u043e \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0441\u0440\u0435\u0434\u0435. \u042d\u0442\u043e \u043a\u043e\u0440\u0440\u0435\u043b\u0438\u0440\u0443\u0435\u0442 \u0441:\n\n\u0418\u043d\u0441\u0442\u0438\u043d\u043a\u0442\u043e\u043c \u0441\u0430\u043c\u043e\u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u0449\u0438\u0442\u044b: \u0410\u043a\u0442\u0438\u0432\u043d\u044b\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043f\u043e \u043e\u0442\u0441\u0442\u0430\u0438\u0432\u0430\u043d\u0438\u044e \u0441\u0432\u043e\u0438\u0445 \u0433\u0440\u0430\u043d\u0438\u0446, \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u043e\u0432, \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438. \u042d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u043e\u044f\u0432\u043b\u044f\u0442\u044c\u0441\u044f \u043a\u0430\u043a \u0440\u0435\u0448\u0438\u043c\u043e\u0441\u0442\u044c, \u0441\u043c\u0435\u043b\u043e\u0441\u0442\u044c, \u043d\u0430\u043f\u043e\u0440\u0438\u0441\u0442\u043e\u0441\u0442\u044c, \u0430 \u0432 \u043a\u0440\u0430\u0439\u043d\u0438\u0445 \u0441\u043b\u0443\u0447\u0430\u044f\u0445 \u2013 \u043a\u0430\u043a \u0430\u0433\u0440\u0435\u0441\u0441\u0438\u044f \u0438\u043b\u0438 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u043d\u043e\u0441\u0442\u044c.\n\n\u041f\u0440\u043e\u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c\u044e \u0438 \u0438\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u043e\u0439: \u0421\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u0438\u043d\u0438\u0446\u0438\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f, \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u0432\u0430\u0442\u044c \u043f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0438\u044f, \u0434\u043e\u0431\u0438\u0432\u0430\u0442\u044c\u0441\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0446\u0435\u043b\u0435\u0439. \u042d\u0442\u043e \u043f\u0440\u0438\u043d\u0446\u0438\u043f "\u0434\u0435\u043b\u0430\u043d\u0438\u044f" \u0438 \u0441\u0430\u043c\u043e\u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f.\n\n\u0424\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0438\u0435\u0439 \u0438 \u0432\u044b\u043d\u043e\u0441\u043b\u0438\u0432\u043e\u0441\u0442\u044c\u044e: \u041c\u0430\u0440\u0441 \u0441\u0432\u044f\u0437\u0430\u043d \u0441 \u0442\u0435\u043b\u0435\u0441\u043d\u043e\u0439 \u0441\u0438\u043b\u043e\u0439, \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c\u044e \u043a \u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0443\u0441\u0438\u043b\u0438\u044f\u043c \u0438 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u0438.\n\n\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u043c \u0441\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u043c \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c (\u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f): \u0425\u043e\u0442\u044f \u0446\u0438\u043a\u043b \u041c\u0430\u0440\u0441\u0430 \u0435\u0449\u0435 \u043d\u0435 \u0441\u0442\u043e\u043b\u044c \u0434\u043b\u0438\u0442\u0435\u043b\u0435\u043d, \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u0432\u0435\u0447\u0430\u0442\u044c \u0437\u0430 \u0441\u043b\u043e\u0436\u043d\u044b\u0435 \u0441\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b (\u043a\u0430\u043a \u0443 \u042e\u043f\u0438\u0442\u0435\u0440\u0430), \u043e\u043d \u0443\u0436\u0435 \u0438\u043c\u0435\u0435\u0442 \u0441\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0442\u0435\u043d\u043e\u043a. \u042d\u0442\u043e \u043f\u0440\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0432 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043a\u043e\u043e\u043f\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u0434\u043b\u044f \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u043e\u0431\u0449\u0438\u0445 \u0446\u0435\u043b\u0435\u0439 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432 \u043a\u043e\u043c\u0430\u043d\u0434\u0435, \u0433\u0440\u0443\u043f\u043f\u0435), \u043a\u043e\u043d\u043a\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0438\u043b\u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u0442\u044c "\u0441\u0432\u043e\u0438\u0445".\n\n\u0421\u043e\u0431\u044b\u0442\u0438\u044f \u0438 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u044b, \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0435 \u0441 \u0446\u0438\u043a\u043b\u043e\u043c \u041c\u0430\u0440\u0441\u0430 (1-2 \u0433\u043e\u0434\u0430), \u0447\u0430\u0441\u0442\u043e \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0443\u0441\u0438\u043b\u0438\u0439, \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u043d\u0430\u0432\u044b\u043a\u043e\u0432 \u0438 \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u0438 \u0432\u044b\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044c \u043d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u0438\u0435 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u0438\u043b\u0438 \u0434\u0430\u0436\u0435 \u0434\u043e \u043f\u0430\u0440\u044b \u043b\u0435\u0442. \u042d\u0442\u043e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u043f\u0440\u043e\u0435\u043a\u0442\u0430\u043c, \u0442\u0440\u0435\u0431\u0443\u044e\u0449\u0438\u043c \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0432\u043d\u0435\u0434\u0440\u0435\u043d\u0438\u044f, \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u043d\u0438\u044f \u0441\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u0435\u043d\u0438\u044f \u0438\u043b\u0438 \u043e\u0441\u0432\u043e\u0435\u043d\u0438\u044f \u043d\u043e\u0432\u044b\u0445 \u043e\u0431\u043b\u0430\u0441\u0442\u0435\u0439 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.',null,B.b,null,null)
